# times.ps1 - computes the timetable from the journal and writes _session/this_repo/timetable.md.
# Same journal, same bytes. Reads the journal only; writes that one generated file.
#
# Columns: user (reply -> next prompt), assistant (prompt -> reply), running (run start -> run end),
# adjust (lines dictated by the user). An interval of more than 2 hours counts zero until a
# "gap" line answers it. No break is assumed.

$ErrorActionPreference = 'Stop'
. (Join-Path $PSScriptRoot 'lib.ps1')
$p = Get-SessionPaths
$journal = @(Read-Journal)

$perTask = @{}
$perDay = @{}
function Add-Hours([string]$task, [string]$day, [string]$column, [double]$hours) {
    if (-not $perTask.ContainsKey($task)) { $perTask[$task] = @{ user = 0.0; assistant = 0.0; running = 0.0; adjust = 0.0; first = ''; last = '' } }
    if (-not $perDay.ContainsKey($day)) { $perDay[$day] = @{ user = 0.0; assistant = 0.0; running = 0.0; adjust = 0.0 } }
    $perTask[$task][$column] += $hours
    $perDay[$day][$column] += $hours
}

# Answers to gaps: timecode of the line before the gap -> task, hours
$answers = @{}
foreach ($row in $journal) {
    if ($row.Text -match '^gap (\d{8}_\d{6}) (\d+(?:\.\d+)?)h') {
        $answers[$Matches[1]] = @{ Task = $row.Task; Hours = [double]::Parse($Matches[2], $script:Inv) }
    }
}

$inTurn = $false
$runStart = @{}
$openGaps = @()
$counted = @()
for ($i = 0; $i -lt $journal.Count; $i++) {
    $cur = $journal[$i]
    $day = $cur.Code.Substring(0, 8)

    if (-not $perTask.ContainsKey($cur.Task)) { Add-Hours $cur.Task $day 'user' 0.0 }
    if (-not $perTask[$cur.Task].first) { $perTask[$cur.Task].first = $cur.Code }
    $perTask[$cur.Task].last = $cur.Code

    if ($i -gt 0) {
        $prev = $journal[$i - 1]
        $hours = ((ConvertTo-Time $cur.Code) - (ConvertTo-Time $prev.Code)).TotalHours
        if ($hours -gt 0) {
            $column = 'user'
            if ($inTurn -and $cur.Text -notmatch '^session start') { $column = 'assistant' }
            if ($hours -gt 2) {
                if ($answers.ContainsKey($prev.Code)) {
                    Add-Hours $answers[$prev.Code].Task $day 'user' $answers[$prev.Code].Hours
                } else {
                    $openGaps += ("| {0} | {1} | {2} | {3} |" -f $prev.Code, $cur.Code, (Format-Hours $hours), $prev.Task)
                }
            } else {
                Add-Hours $cur.Task $day $column $hours
                if ($hours -ge 0.25) { $counted += ("| {0} | {1} | {2} | {3} | {4} |" -f $prev.Code, $cur.Code, (Format-Hours $hours), $cur.Task, $column) }
            }
        }
    }

    if ($cur.Text -match '^prompt\b') { $inTurn = $true }
    elseif ($cur.Text -match '^(reply\b|session start)') { $inTurn = $false }

    if ($cur.Text -match '^run start') { $runStart[$cur.Task] = $cur.Code }
    elseif ($cur.Text -match '^run end' -and $runStart.ContainsKey($cur.Task)) {
        $h = ((ConvertTo-Time $cur.Code) - (ConvertTo-Time $runStart[$cur.Task])).TotalHours
        Add-Hours $cur.Task $day 'running' $h
        $runStart.Remove($cur.Task)
    }
    elseif ($cur.Text -match '^adjust ([+-]?\d+(?:\.\d+)?)h') {
        Add-Hours $cur.Task $day 'adjust' ([double]::Parse($Matches[1], $script:Inv))
    }
}

$titles = @{}
foreach ($t in (Get-TaskFiles)) { $titles[$t.Id] = ('{0} ({1})' -f $t.Title, $t.State) }

$out = New-Object System.Collections.Generic.List[string]
$out.Add('# Timetable')
$out.Add('')
$out.Add('GENERATED by `_session/kit/tools/times.ps1` from the journal. Do not edit.')
$out.Add('Hours. user = reply to next prompt; assistant = prompt to reply; running =')
$out.Add('run start to run end; adjust = dictated by the user. Intervals over 2 hours')
$out.Add('count zero until a `gap` line answers them.')
$out.Add('')
$out.Add('## Per Task')
$out.Add('')
$out.Add('| Task | Title | First line | Last line | User | Assistant | Running | Adjust | Sum |')
$out.Add('|---|---|---|---|---|---|---|---|---|')
$total = @{ user = 0.0; assistant = 0.0; running = 0.0; adjust = 0.0 }
foreach ($task in ($perTask.Keys | Sort-Object)) {
    $r = $perTask[$task]
    $sum = $r.user + $r.assistant + $r.running + $r.adjust
    $title = ''
    if ($titles.ContainsKey($task)) { $title = $titles[$task] }
    if ($task -eq 'T000') { $title = '(no task)' }
    $out.Add(('| {0} | {1} | {2} | {3} | {4} | {5} | {6} | {7} | {8} |' -f $task, $title, $r.first, $r.last, (Format-Hours $r.user), (Format-Hours $r.assistant), (Format-Hours $r.running), (Format-Hours $r.adjust), (Format-Hours $sum)))
    foreach ($k in 'user', 'assistant', 'running', 'adjust') { $total[$k] += $r[$k] }
}
$grand = $total.user + $total.assistant + $total.running + $total.adjust
$out.Add(('| **All** | | | | {0} | {1} | {2} | {3} | {4} |' -f (Format-Hours $total.user), (Format-Hours $total.assistant), (Format-Hours $total.running), (Format-Hours $total.adjust), (Format-Hours $grand)))
$out.Add('')
$out.Add('## Per Day')
$out.Add('')
$out.Add('| Day | User | Assistant | Running | Adjust | Sum |')
$out.Add('|---|---|---|---|---|---|')
foreach ($day in ($perDay.Keys | Sort-Object)) {
    $r = $perDay[$day]
    $out.Add(('| {0} | {1} | {2} | {3} | {4} | {5} |' -f $day, (Format-Hours $r.user), (Format-Hours $r.assistant), (Format-Hours $r.running), (Format-Hours $r.adjust), (Format-Hours ($r.user + $r.assistant + $r.running + $r.adjust))))
}
$out.Add('')
$out.Add('## Open Gaps (over 2 hours, counted zero, ask the user)')
$out.Add('')
if ($openGaps.Count -eq 0) { $out.Add('None.') }
else {
    $out.Add('| After | Until | Hours | Task before |')
    $out.Add('|---|---|---|---|')
    foreach ($line in $openGaps) { $out.Add($line) }
}
$out.Add('')
$out.Add('## Runs Not Ended')
$out.Add('')
if ($runStart.Count -eq 0) { $out.Add('None.') }
else { foreach ($task in ($runStart.Keys | Sort-Object)) { $out.Add(('- {0}: run start {1}' -f $task, $runStart[$task])) } }
$out.Add('')
$out.Add('## Counted Intervals of 15 Minutes to 2 Hours (correct with an `adjust` line)')
$out.Add('')
if ($counted.Count -eq 0) { $out.Add('None.') }
else {
    $out.Add('| From | To | Hours | Task | Column |')
    $out.Add('|---|---|---|---|---|')
    foreach ($line in $counted) { $out.Add($line) }
}

$file = Join-Path $p.This 'timetable.md'
Write-TextFile $file $out.ToArray()
Write-Output ("Written: {0}" -f $file)
Write-Output ("Tasks: {0}. Sum: {1} hours. Open gaps: {2}. Runs not ended: {3}." -f $perTask.Count, (Format-Hours $grand), $openGaps.Count, $runStart.Count)
